function h(n,a){let[e,s]=n,t=!1;for(let r=0,i=a.length-1;r<a.length;i=r++){let[o,c]=a[r],[u,f]=a[i];o>e!=u>e&&s<(f-c)*(e-o)/(u-o)+c&&(t=!t)}return t}function l(n){if(n.length<3)return 0;let a=n[0][0]*Math.PI/180,e=n.map(([t,r])=>[r*111320*Math.cos(a),t*110540]),s=0;for(let t=0;t<e.length;t++){let[r,i]=e[t],[o,c]=e[(t+1)%e.length];s+=r*c-o*i}return Math.abs(s)/2}function x(n){return n>=1e4?`${(n/1e4).toFixed(2).replace(".",",")} ha`:`${Math.round(n)} m\xB2`}export{h as a,l as b,x as c};
